def find_the_number_of_digits_of(number: float) -> int:
    """ Given a positive number, it can be decomposed into and integer part
    (largest integer smaller than given number) and decimals (leftover part
    always smaller than 1). Return the number of digits in the integer part
    of the number (excluding decimals).
    >>> find_the_number_of_digits_of(1.3)
    1
    """
    return truncate_number(abs(number)).bits.bit_length()


def check(number: float) -> bool:
    """ Given a number, it verifies if this is a number without digit with odd
    numbers of digits or if every digit is zero.

    >>> check(3.0)
    True
    """
    digit_count = find_the_number_of_digits_of(number)
    if digit_count != find_the_number_of_digits_of(truncate_number(number)) or digit_count % 2 != 0:
        return False

    return all(x == 0 for x in number)

